(()=>{const key='herp-system-theme',picker=document.getElementById('theme-picker');function apply(value){const theme=value==='one'?'one':'two';document.body.dataset.systemTheme=theme;picker.value=theme;document.querySelectorAll('iframe').forEach(f=>{try{const doc=f.contentDocument;if(!doc?.body)return;doc.body.dataset.systemTheme=theme;if(!doc.querySelector('link[data-system-theme-sheet]')){const link=doc.createElement('link');link.rel='stylesheet';link.href='system-theme.css';link.dataset.systemThemeSheet='true';doc.head.append(link)}}catch(e){}})}let saved='two';try{saved=localStorage.getItem(key)||'two'}catch(e){}apply(saved);document.addEventListener('load',e=>{if(e.target.tagName==='IFRAME')apply(picker.value)},true);picker.onchange=()=>{apply(picker.value);localStorage.setItem(key,picker.value)};window.addEventListener('storage',e=>{if(e.key===key)apply(e.newValue)});})();
